import{_ as l,a0 as p,w as o,s as r,ao as c,I as t,x as i,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Linux 中使用 Asciinema 进行录制和回放终端会话 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中使用 Asciinema 进行录制和回放终端会话 | LCTT (201705) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中使用 Asciinema 进行录制和回放终端会话 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中使用 Asciinema 进行录制和回放终端会话 | LCTT (201705) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201705/20170203 Record and Replay Terminal Session with Asciinema on Linux","title":"如何在 Linux 中使用 Asciinema 进行录制和回放终端会话","tag":"201705","desc":""},"relativePath":"201705/20170203 Record and Replay Terminal Session with Asciinema on Linux.md","filePath":"[post].md"}'),h={name:"201705/20170203 Record and Replay Terminal Session with Asciinema on Linux.md"};function d(g,s,k,b,u,m){const a=p("Link");return o(),r("div",null,[s[13]||(s[13]=c(`<h1 id="如何在-linux-中使用-asciinema-进行录制和回放终端会话" tabindex="-1">如何在 Linux 中使用 Asciinema 进行录制和回放终端会话 <a class="header-anchor" href="#如何在-linux-中使用-asciinema-进行录制和回放终端会话" aria-label="Permalink to “如何在 Linux 中使用 Asciinema 进行录制和回放终端会话”">​</a></h1><p><img src="https://linuxconfig.org/images/asciimena-video-example.jpg?58942057" alt=""></p><h3 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to “简介”">​</a></h3><p>Asciinema 是一个轻量并且非常高效的终端会话录制器。使用它可以录制、回放和分享 JSON 格式的终端会话记录。与一些桌面录制器，比如 Recordmydesktop、Simplescreenrecorder、Vokoscreen 或 Kazam 相比，Asciinema 最主要的优点是，它能够以通过 ASCII 文本以及 ANSI 转义码编码来录制所有的标准终端输入、输出和错误信息。</p><p>事实上，即使是很长的终端会话，录制出的 JSON 格式文件也非常小。另外，JSON 格式使得用户可以利用简单的文件转化器，将输出的 JSON 格式文件嵌入到 HTML 代码中，然后分享到公共网站或者使用 asciinema 账户分享到 Asciinema.org 。最后，如果你的终端会话中有一些错误，并且你还懂一些 ASCI 转义码语法，那么你可以使用任何编辑器来修改你的已录制终端会话。</p><p><strong>难易程度：</strong></p><p>很简单！</p><p><strong>标准终端：</strong></p><ul><li><strong>#</strong> - 给定命令需要以 root 用户权限运行或者使用 <code>sudo</code> 命令</li><li><strong>$</strong> - 给定命令以常规权限用户运行</li></ul><h3 id="从软件库安装" tabindex="-1">从软件库安装 <a class="header-anchor" href="#从软件库安装" aria-label="Permalink to “从软件库安装”">​</a></h3><p>通常， asciinema 可以使用你的发行版的软件库进行安装。但是，如果不可以使用系统的软件库进行安装或者你想安装最新的版本，那么，你可以像下面的“从源代码安装”部分所描述的那样，使用 Linuxbrew 包管理器来执行 Asciinema 安装。</p><p><strong>在 Arch Linux 上安装：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pacman -S asciinema</span></span></code></pre></div><p><strong>在 Debian 上安装：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt install asciinema</span></span></code></pre></div><p><strong>在 Ubuntu 上安装：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install asciinema</span></span></code></pre></div><p><strong>在 Fedora 上安装：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install asciinema</span></span></code></pre></div><h3 id="从源代码安装" tabindex="-1">从源代码安装 <a class="header-anchor" href="#从源代码安装" aria-label="Permalink to “从源代码安装”">​</a></h3><p>最简单并且值得推荐的方式是使用 Linuxbrew 包管理器，从源代码安装最新版本的 Asciinema 。</p><h4 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to “前提条件”">​</a></h4><p>下面列出的前提条件是安装 Linuxbrew 和 Asciinema 需要满足的依赖关系：</p><ul><li>git</li><li>gcc</li><li>make</li><li>ruby</li></ul><p>在安装 Linuxbrew 之前，请确保上面的这些包都已经安装在了你的 Linux 系统中。</p><p><strong>在 Arch Linux 上安装 ruby：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pacman -S git gcc make ruby</span></span></code></pre></div><p><strong>在 Debian 上安装 ruby：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt install git gcc make ruby</span></span></code></pre></div><p><strong>在 Ubuntu 上安装 ruby：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install git gcc make ruby</span></span></code></pre></div><p><strong>在 Fedora 上安装 ruby：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install git gcc make ruby</span></span></code></pre></div><p><strong>在 CentOS 上安装 ruby：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install git gcc make ruby</span></span></code></pre></div><h4 id="安装-linuxbrew" tabindex="-1">安装 Linuxbrew <a class="header-anchor" href="#安装-linuxbrew" aria-label="Permalink to “安装 Linuxbrew”">​</a></h4><p>Linuxbrew 包管理器是苹果的 MacOS 操作系统很受欢迎的 Homebrew 包管理器的一个复刻版本。还没发布多久，Homebrew 就以容易使用而著称。如果你想使用 Linuxbrew 来安装 Asciinema，那么，请运行下面命令在你的 Linux 版本上安装 Linuxbrew：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ruby -e &quot;$(curl -fsSL https://raw.githubusercontent.com/Linuxbrew/install/master/install)&quot;</span></span></code></pre></div><p>现在，Linuxbrew 已经安装到了目录 <code>$HOME/.linuxbrew/</code> 下。剩下需要做的就是使它成为可执行 <code>PATH</code> 环境变量的一部分。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;export PATH=&quot;$HOME/.linuxbrew/bin:$PATH&quot;&#39; &gt;&gt;~/.bash_profile</span></span>
<span class="line"><span>$ . ~/.bash_profile</span></span></code></pre></div><p>为了确认 Linuxbrew 是否已经安装好，你可以使用 <code>brew</code> 命令来查看它的版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ brew --version</span></span>
<span class="line"><span>Homebrew 1.1.7</span></span>
<span class="line"><span>Homebrew/homebrew-core (git revision 5229; last commit 2017-02-02)</span></span></code></pre></div><h4 id="安装-asciinema" tabindex="-1">安装 Asciinema <a class="header-anchor" href="#安装-asciinema" aria-label="Permalink to “安装 Asciinema”">​</a></h4><p>安装好 Linuxbrew 以后，安装 Asciinema 就变得无比容易了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ brew install asciinema</span></span></code></pre></div><p>检查 Asciinema 是否安装正确：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ asciinema --version</span></span>
<span class="line"><span>asciinema 1.3.0</span></span></code></pre></div><h3 id="录制终端会话" tabindex="-1">录制终端会话 <a class="header-anchor" href="#录制终端会话" aria-label="Permalink to “录制终端会话”">​</a></h3><p>经过一番辛苦的安装工作以后，是时候来干一些有趣的事情了。Asciinema 是一个非常容易使用的软件。事实上，目前的 1.3 版本只有很少的几个可用命令行选项，其中一个是 <code>--help</code> 。</p><p>我们首先使用 <code>rec</code> 选项来录制终端会话。下面的命令将会开始录制终端会话，之后，你将会有一个选项来丢弃已录制记录或者把它上传到 asciinema.org 网站以便将来参考。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ asciinema rec</span></span></code></pre></div><p>运行上面的命令以后，你会注意到， Asciinema 已经开始录制终端会话了，你可以按下 <code>CTRL+D</code> 快捷键或执行 <code>exit</code> 命令来停止录制。如果你使用的是 Debian/Ubuntu/Mint Linux 系统，你可以像下面这样尝试进行第一次 asciinema 录制：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ su</span></span>
<span class="line"><span>Password:</span></span>
<span class="line"><span># apt install sl</span></span>
<span class="line"><span># exit</span></span>
<span class="line"><span>$ sl</span></span></code></pre></div><p>一旦输入最后一个 <code>exit</code> 命令以后，将会询问你：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ exit</span></span>
<span class="line"><span>~ Asciicast recording finished.</span></span>
<span class="line"><span>~ Press &lt;Enter&gt; to upload, &lt;Ctrl-C&gt; to cancel.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>https://asciinema.org/a/7lw94ys68gsgr1yzdtzwijxm4</span></span></code></pre></div><p>如果你不想上传你的私密命令行技巧到 asciinema.org 网站，那么有一个选项可以把 Asciinema 记录以 JSON 格式保存为本地文件。比如，下面的 asciinema 记录将被存为 <code>/tmp/my_rec.json</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ asciinema rec /tmp/my_rec.json</span></span></code></pre></div><p>另一个非常有用的 asciinema 特性是时间微调。如果你的键盘输入速度很慢，或者你在进行多任务，输入命令和执行命令之间的时间会比较长。Asciinema 会记录你的实时按键时间，这意味着每一个停顿都将反映在最终视频的长度上。可以使用 <code>-w</code> 选项来缩短按键的时间间隔。比如，下面的命令将按键的时间间隔缩短为 0.2 秒：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ asciinema rec -w 0.2</span></span></code></pre></div><h3 id="回放已录制终端会话" tabindex="-1">回放已录制终端会话 <a class="header-anchor" href="#回放已录制终端会话" aria-label="Permalink to “回放已录制终端会话”">​</a></h3><p>有两种方式可以来回放已录制会话。第一种方式是直接从 asciinema.org 网站上播放终端会话。这意味着，你之前已经把录制会话上传到了 asciinema.org 网站，并且需要提供有效链接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ asciinema play https://asciinema.org/a/7lw94ys68gsgr1yzdtzwijxm4</span></span></code></pre></div><p>另外，你也可以使用本地存储的 JSON 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ asciinema play /tmp/my_rec.json</span></span></code></pre></div><p>如果要使用 <code>wget</code> 命令来下载之前的上传记录，只需在链接的后面加上 <code>.json</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget -q -O steam_locomotive.json https://asciinema.org/a/7lw94ys68gsgr1yzdtzwijxm4.json</span></span>
<span class="line"><span>$ asciinema play steam_locomotive.json</span></span></code></pre></div><h3 id="将视频嵌入-html" tabindex="-1">将视频嵌入 HTML <a class="header-anchor" href="#将视频嵌入-html" aria-label="Permalink to “将视频嵌入 HTML”">​</a></h3><p>最后，asciinema 还带有一个独立的 JavaScript 播放器。这意味者你可以很容易的在你的网站上分享终端会话记录。下面，使用一段简单的 <code>index.html</code> 代码来说明这个方法。首先，下载所有必要的东西：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /tmp/</span></span>
<span class="line"><span>$ mkdir steam_locomotive</span></span>
<span class="line"><span>$ cd steam_locomotive/</span></span>
<span class="line"><span>$ wget -q -O steam_locomotive.json https://asciinema.org/a/7lw94ys68gsgr1yzdtzwijxm4.json</span></span>
<span class="line"><span>$ wget -q https://github.com/asciinema/asciinema-player/releases/download/v2.4.0/asciinema-player.css</span></span>
<span class="line"><span>$ wget -q https://github.com/asciinema/asciinema-player/releases/download/v2.4.0/asciinema-player.js</span></span></code></pre></div><p>之后，创建一个新的包含下面这些内容的 <code>/tmp/steam_locomotive/index.html</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;html&gt;</span></span>
<span class="line"><span>&lt;head&gt;</span></span>
<span class="line"><span>  &lt;link rel=&quot;stylesheet&quot; type=&quot;text/css&quot; href=&quot;./asciinema-player.css&quot; /&gt;</span></span>
<span class="line"><span>&lt;/head&gt;</span></span>
<span class="line"><span>&lt;body&gt;</span></span>
<span class="line"><span>  &lt;asciinema-player src=&quot;./steam_locomotive.json&quot; cols=&quot;80&quot; rows=&quot;24&quot;&gt;&lt;/asciinema-player&gt;</span></span>
<span class="line"><span>  &lt;script src=&quot;./asciinema-player.js&quot;&gt;&lt;/script&gt;</span></span>
<span class="line"><span>&lt;/body&gt;</span></span>
<span class="line"><span>&lt;/html&gt;</span></span></code></pre></div><p>完成以后，打开你的网页浏览器，按下 <code>CTRL+O</code> 来打开新创建的 <code>/tmp/steam_locomotive/index.html</code> 文件。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>正如前面所说的，使用 asciinema 录制器来录制终端会话最主要的优点是它的输出文件非常小，这使得你的视频很容易分享出去。上面的例子产生了一个包含 58472 个字符的文件，它是一个只有 58 KB 大 小的 22 秒终端会话视频。如果我们查看输出的 JSON 文件，会发现甚至这个数字已经非常大了，这主要是因为一个 “蒸汽机车” 已经跑过了终端。这个长度的正常终端会话一般会产生一个更小的输出文件。</p><p>下次，当你想要在一个论坛上询问关于 Linux 配置的问题，并且很难描述你的问题的时候，只需运行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ asciinema rec</span></span></code></pre></div><p>然后把最后的链接贴到论坛的帖子里。</p><h3 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to “故障排除”">​</a></h3><h4 id="在-utf-8-环境下运行-asciinema" tabindex="-1">在 UTF-8 环境下运行 asciinema <a class="header-anchor" href="#在-utf-8-环境下运行-asciinema" aria-label="Permalink to “在 UTF-8 环境下运行 asciinema”">​</a></h4><p>错误信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>asciinema needs a UTF-8 native locale to run. Check the output of \`locale\` command.</span></span></code></pre></div><p>解决方法： 生成并导出 UTF-8 语言环境。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ localedef -c -f UTF-8 -i en_US en_US.UTF-8</span></span>
<span class="line"><span>$ export LC_ALL=en_US.UTF-8</span></span></code></pre></div><hr>`,84)),t("p",null,[s[1]||(s[1]=i("via: ",-1)),e(a,{href:"https://linuxconfig.org/record-and-replay-terminal-session-with-asciinema-on-linux"},{default:n(()=>[...s[0]||(s[0]=[i("https://linuxconfig.org/record-and-replay-terminal-session-with-asciinema-on-linux",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=i("作者：",-1)),e(a,{href:"https://linuxconfig.org/record-and-replay-terminal-session-with-asciinema-on-linux"},{default:n(()=>[...s[2]||(s[2]=[i("Lubos Rendek",-1)])]),_:1}),s[6]||(s[6]=i(" 译者：",-1)),e(a,{href:"https://github.com/ucasFL"},{default:n(()=>[...s[3]||(s[3]=[i("ucasFL",-1)])]),_:1}),s[7]||(s[7]=i(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[4]||(s[4]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=i("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[8]||(s[8]=[i("LCTT",-1)])]),_:1}),s[11]||(s[11]=i(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:n(()=>[...s[9]||(s[9]=[i("Linux中国",-1)])]),_:1}),s[12]||(s[12]=i(" 荣誉推出",-1))])])}const C=l(h,[["render",d]]);export{x as __pageData,C as default};
